/* global Office */

Office.onReady(() => {
  // If needed, Office.js is ready to be called.
});

/**
 * Shows a notification when the add-in command is executed.
 * @param event {Office.AddinCommands.Event}
 */
function action(event) {
  const message = {
    type: Office.MailboxEnums.ItemNotificationMessageType.InformationalMessage,
    message: "Performed action.",
    icon: "Icon.80x80",
    persistent: true,
  };

  Office.context.mailbox.item.notificationMessages.replaceAsync(
    "ActionPerformanceNotification",
    message
  );

  event.completed();
}

// Register the function with Office.
Office.actions.associate("action", action);


/* =========================================================================
   ASSINATURA AUTOMATICA - MONFREDINI TRANSPORTES
   =========================================================================
   Roda sozinho toda vez que a pessoa clica em "Novo E-mail" (evento
   OnNewMessageCompose, configurado no manifest.xml).

   Como funciona:
   1) Descobre o e-mail de quem esta escrevendo.
   2) Baixa a lista de colaboradores (arquivo colaboradores.json, que fica
      no mesmo GitHub Pages do Add-in). Esse arquivo e gerado pelo script
      Gerar-ColaboradoresJson.ps1 a partir da lista do SharePoint.
   3) Se a pessoa esta na lista, insere a assinatura (nome + telefone) com
      logo/selos/grafismo embutidos como imagens "inline".
      Se NAO esta na lista, nao mexe em nada.

   Para incluir/alterar pessoas NAO precisa mexer neste codigo nem rodar
   "npm run build": basta atualizar o colaboradores.json no GitHub.

   Seguranca: se o arquivo nao puder ser baixado (sem internet, GitHub fora
   do ar), usa so a lista de reserva abaixo (DADOS_RESERVA).
   ========================================================================= */

// Endereco do arquivo com a lista de colaboradores (mesmo site do Add-in).
const URL_COLABORADORES = "https://nicolassilva-spec.github.io/assinatura-outlook-addin/colaboradores.json";

// Tempo maximo esperando o download da lista (milissegundos).
const TEMPO_LIMITE_DOWNLOAD_MS = 8000;

// Lista de reserva: so vale se o download falhar. Mantem pelo menos o
// cadastro de teste funcionando.
const DADOS_RESERVA = {
  "nicolas.silva@monfredinitransportes.com.br": {
    nome: "Nicolas Silva",
    cargo: "Auxiliar de TI",
    telefone: "(12) 98277-0045",
  },
};

// As 4 imagens da assinatura (logo, selos, grafismo e o iconezinho de
// telefone), ja convertidas para texto (base64), para nao precisar de
// nenhum link publico na internet - elas viajam dentro do proprio Add-in
// e sao anexadas no e-mail como imagem embutida.
const IMG_LOGO_BASE64 = "";
const IMG_SELOS_BASE64 = "";
const IMG_GRAFISMO_BASE64 = "";
const IMG_TELEFONE_BASE64 = "";

// Troca caracteres especiais por codigos HTML, para que um nome como
// "Joao <teste>" nunca quebre ou injete HTML na assinatura.
function escaparHtml(texto) {
  return String(texto === undefined || texto === null ? "" : texto)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// Baixa o colaboradores.json. Sempre chama aoTerminar(lista), mesmo se der
// erro (nesse caso entrega so a lista de reserva).
function carregarColaboradores(aoTerminar) {
  let terminou = false;
  const finalizar = function (listaRemota) {
    if (terminou) {
      return;
    }
    terminou = true;
    const lista = {};
    Object.keys(DADOS_RESERVA).forEach(function (email) {
      lista[email.toLowerCase()] = DADOS_RESERVA[email];
    });
    if (listaRemota && typeof listaRemota === "object") {
      Object.keys(listaRemota).forEach(function (email) {
        lista[email.toLowerCase()] = listaRemota[email];
      });
    }
    aoTerminar(lista);
  };

  try {
    const pedido = new XMLHttpRequest();
    // "?t=" evita pegar uma copia antiga guardada em cache.
    pedido.open("GET", URL_COLABORADORES + "?t=" + Date.now(), true);
    pedido.timeout = TEMPO_LIMITE_DOWNLOAD_MS;
    pedido.onload = function () {
      if (pedido.status >= 200 && pedido.status < 300) {
        try {
          finalizar(JSON.parse(pedido.responseText));
        } catch (erroLeitura) {
          console.error("colaboradores.json invalido: " + erroLeitura.message);
          finalizar(null);
        }
      } else {
        console.error("Falha ao baixar colaboradores.json. Status: " + pedido.status);
        finalizar(null);
      }
    };
    pedido.onerror = function () {
      console.error("Erro de rede ao baixar colaboradores.json");
      finalizar(null);
    };
    pedido.ontimeout = function () {
      console.error("Tempo esgotado ao baixar colaboradores.json");
      finalizar(null);
    };
    pedido.send();
  } catch (erro) {
    console.error("Erro ao iniciar download: " + erro.message);
    finalizar(null);
  }

  // Rede de seguranca extra, caso nenhum dos eventos acima dispare.
  setTimeout(function () {
    finalizar(null);
  }, TEMPO_LIMITE_DOWNLOAD_MS + 2000);
}

function montarHtmlAssinatura(dados) {
  // Nome sempre em maiusculas (feito aqui porque o Outlook para Windows
  // ignora "text-transform").
  const nomeTexto = String(dados.nome || "").toUpperCase();
  const nome = escaparHtml(nomeTexto);
  const cargo = escaparHtml(dados.cargo);
  const telefone = escaparHtml(dados.telefone);

  // Nomes muito longos diminuem um pouco para nao quebrar em duas linhas.
  const tamanhoNome = nomeTexto.length <= 22 ? 18 : nomeTexto.length <= 27 ? 15 : 13;

  const fonte = "font-family: Montserrat, Arial, Helvetica, sans-serif;";

  const linhaCargo = cargo
    ? '<tr><td style="' + fonte + " padding: 3px 0 0 0; font-size: 14px; line-height: 16px; color: #4B4747; mso-line-height-rule: exactly;\">" +
      cargo +
      "</td></tr>"
    : "";

  const linhaTelefone = telefone
    ? '<tr><td style="' + fonte + " padding: 4px 0 0 0; font-size: 11px; line-height: 16px; color: #000000; mso-line-height-rule: exactly;\">" +
      '<img src="cid:telefone-icone.png" width="14" height="14" alt="" style="vertical-align: middle; margin-right: 3px; border: 0;" />' +
      telefone +
      "</td></tr>"
    : "";

  // Layout (700 x 150 px): logo | texto (nome, linha vermelha, cargo,
  // telefone, selos) | grafismo na lateral direita.
  return (
    '<table cellpadding="0" cellspacing="0" border="0" width="700" style="width: 700px; border-collapse: collapse; background-color: #ffffff;">' +
    "<tr>" +
    // Coluna 1: logo
    '<td width="127" valign="middle" style="width: 127px; padding: 0 46px 0 46px;">' +
    '<img src="cid:logo-monfredini.png" width="127" height="104" alt="Monfredini Transportes" style="display: block; border: 0;" /></td>' +
    // Coluna 2: texto
    '<td width="279" valign="top" style="width: 279px; padding: 32px 65px 0 0;">' +
    '<table cellpadding="0" cellspacing="0" border="0" width="279" style="width: 279px; border-collapse: collapse;">' +
    '<tr><td style="' + fonte + " padding: 0; font-size: " + tamanhoNome + "px; line-height: 21px; font-weight: bold; color: #000000; border-bottom: 1px solid #E01A34; mso-line-height-rule: exactly;\">" +
    nome +
    "</td></tr>" +
    linhaCargo +
    linhaTelefone +
    '<tr><td align="right" style="padding: 5px 0 0 0;">' +
    '<img src="cid:selos-certificacoes.png" width="165" height="25" alt="" style="display: block; border: 0;" /></td></tr>' +
    "</table></td>" +
    // Coluna 3: grafismo
    '<td width="137" valign="top" style="width: 137px; padding: 0;">' +
    '<img src="cid:grafismo-lateral.png" width="137" height="150" alt="" style="display: block; border: 0;" /></td>' +
    "</tr></table>"
  );
}

function onNewMessageComposeHandler(event) {
  let encerrado = false;
  const encerrar = function () {
    if (!encerrado) {
      encerrado = true;
      event.completed();
    }
  };

  try {
    const emailUsuario = (Office.context.mailbox.userProfile.emailAddress || "").toLowerCase();

    carregarColaboradores(function (colaboradores) {
      const dados = colaboradores[emailUsuario];

      if (!dados || !dados.nome) {
        // Pessoa fora da lista (ou cadastro sem nome): nao mexe na
        // assinatura dela, so encerra o evento normalmente.
        encerrar();
        return;
      }

      const html = montarHtmlAssinatura(dados);

      anexarImagem("logo-monfredini.png", IMG_LOGO_BASE64, function () {
        anexarImagem("selos-certificacoes.png", IMG_SELOS_BASE64, function () {
          anexarImagem("grafismo-lateral.png", IMG_GRAFISMO_BASE64, function () {
            anexarImagem("telefone-icone.png", IMG_TELEFONE_BASE64, function () {
              Office.context.mailbox.item.body.setSignatureAsync(
                html,
                { coercionType: Office.CoercionType.Html },
                function (asyncResult) {
                  if (asyncResult.status === Office.AsyncResultStatus.Failed) {
                    console.error("Falha ao definir assinatura: " + asyncResult.error.message);
                  }
                  encerrar();
                }
              );
            });
          });
        });
      });
    });
  } catch (erro) {
    console.error("Erro inesperado na assinatura: " + erro.message);
    encerrar();
  }
}

function anexarImagem(nomeArquivo, base64, aoTerminar) {
  Office.context.mailbox.item.addFileAttachmentFromBase64Async(
    base64,
    nomeArquivo,
    { isInline: true },
    function (resultado) {
      if (resultado.status === Office.AsyncResultStatus.Failed) {
        console.error("Falha ao anexar " + nomeArquivo + ": " + resultado.error.message);
      }
      aoTerminar();
    }
  );
}

// Registra a funcao com o Office, usando o MESMO nome configurado no
// manifest.xml (FunctionName="onNewMessageComposeHandler").
Office.actions.associate("onNewMessageComposeHandler", onNewMessageComposeHandler);
